  function usageTable(records){return `<div class="table-scroll"><table class="simple-arsenal-table"><thead><tr><th>${text(label('pitch'))}</th><th>${text(label('usage'))}</th><th>${text(label('average'))}</th><th>${text(label('whiffShort'))}</th></tr></thead><tbody>${mixRows(records).map(([pitch,list])=>{const velocities=list.map(r=>r.speed).filter(Number.isFinite),s=PitchCharts.stats(list),share=100*list.length/(records.length||1);return `<tr class="${state().pitch===pitch?'current-pitch':''}"><th><button data-report-pitch="${text(pitch)}">${pitchTag(pitch)}</button><div class="usage-mini-track"><i style="width:${share}%;background:${color(pitch)}"></i></div></th><td><strong>${share.toFixed(1)}%</strong><small>${list.length}${app.lang==='ko'?'구':' pitches'}</small></td><td><strong>${format(velocities.length?velocities.reduce((a,b)=>a+b,0)/velocities.length:null)}</strong><small>km/h</small></td><td><strong>${format(s.whiffRate)}%</strong><small>${s.whiffs}/${s.swings} ${app.lang==='ko'?'스윙':'swings'}</small></td></tr>`}).join('')}</tbody></table></div>`}
  function velocityChart(records){
    const groups=mixRows(records).filter(([,list])=>list.some(r=>Number.isFinite(r.speed)));if(!groups.length)return `<p>${text(label('noSpeed'))}</p>`;
    const all=groups.flatMap(([,list])=>list.map(r=>r.speed).filter(Number.isFinite)),min=Math.floor((Math.min(...all)-3)/10)*10,max=Math.ceil((Math.max(...all)+3)/10)*10,pos=v=>100*(v-min)/(max-min);
    return `<div class="velocity-summary">${groups.map(([pitch,list])=>{const v=list.map(r=>r.speed).filter(Number.isFinite),low=Math.min(...v),high=Math.max(...v),q1=PitchCharts.quantile(v,.25),q3=PitchCharts.quantile(v,.75),mean=v.reduce((a,b)=>a+b,0)/v.length;return `<div class="velocity-row"><div><span>${pitchTag(pitch)}</span><strong>${mean.toFixed(1)} <small>km/h</small></strong><small>${low.toFixed(0)}–${high.toFixed(0)} · n=${v.length}</small></div><div class="velocity-track" role="img" aria-label="${text(pitchLabel(pitch))}: ${low}–${high} km/h, ${label('average')} ${mean.toFixed(1)}" style="--pitch:${color(pitch)}"><i class="velocity-minmax" style="left:${pos(low)}%;width:${pos(high)-pos(low)}%"></i><i class="velocity-iqr" style="left:${pos(q1)}%;width:${Math.max(1,pos(q3)-pos(q1))}%"></i><b style="left:${pos(mean)}%"></b></div></div>`}).join('')}<div class="velocity-axis"><span>${min}</span><span>${(min+max)/2}</span><span>${max} km/h →</span></div></div>`;
  }
  function normalizedZ(r){return [r.plateX,r.plateZ,r.zoneTop,r.zoneBottom].every(Number.isFinite)&&r.zoneTop>r.zoneBottom?(r.plateZ-r.zoneBottom)/(r.zoneTop-r.zoneBottom):null}
  function cellFor(r){const z=normalizedZ(r);if(z===null)return null;const col=Math.floor((r.plateX+1.1805555556)/(.4722222222)),row=Math.floor((4/3-z)/(1/3));return col>=0&&col<5&&row>=0&&row<5?[col,row]:null}
  function locationGrid(rows){
    const valid=rows.filter(r=>normalizedZ(r)!==null),cells=Array.from({length:25},()=>[]);for(const r of valid){const cell=cellFor(r);if(cell)cells[cell[1]*5+cell[0]].push(r)}const max=Math.max(1,...cells.map(c=>c.length));
    if(!valid.length)return `<p class="chart-empty">${text(label('locationMissing'))}</p>`;
    if(state().locationMode==='points'){
      const x=v=>210+v*128,y=v=>335-(v+1/3)*174;
      return `<svg class="arrival-points" viewBox="0 0 420 390" role="group" aria-label="${text(label('locationDensity'))}"><rect x="${x(-17/24)}" y="${y(1)}" width="${128*17/12}" height="174" class="zone-outline"/><path d="M190 355L230 355L230 363L210 378L190 363Z" class="home-plate"/>${valid.filter(r=>Math.abs(r.plateX)<1.5&&normalizedZ(r)>-.4&&normalizedZ(r)<1.5).map(r=>`<circle tabindex="0" role="button" data-report-record="${rows.indexOf(r)}" cx="${x(r.plateX)}" cy="${y(normalizedZ(r))}" r="4.2" fill="${color(r.pitch)}" class="arrival-point"><title>${text(pitchLabel(r.pitch))} · ${format(r.speed)} km/h · ${text(label('result_'+r.result))}</title></circle>`).join('')}<text x="210" y="20" text-anchor="middle">${text(label('aboveZone'))}</text></svg>`;
    }
    return `<div class="density-wrap"><span class="zone-top-label">${text(label('aboveZone'))}</span><div class="arrival-density" role="group" aria-label="${text(label('locationDensity'))}">${cells.map((cell,i)=>`<button class="density-cell ${i%5>=1&&i%5<=3&&Math.floor(i/5)>=1&&Math.floor(i/5)<=3?'in-zone':''} zone-${i}" data-density-cell="${i}" style="--density:${cell.length/max}" aria-label="${app.lang==='ko'?'영역':'Cell'} ${i+1}: ${cell.length}, ${format(100*cell.length/valid.length)}%"><strong>${cell.length?format(100*cell.length/valid.length):'0'}<small>%</small></strong><span>${cell.length}${app.lang==='ko'?'구':' pitches'}</span></button>`).join('')}<div class="density-zone-outline" aria-hidden="true"></div></div><svg class="plate-mark" viewBox="0 0 60 38" aria-hidden="true"><path d="M10 5H50V17L30 33L10 17Z"/></svg><p>${text(recordCountText(valid.length))} · ${valid.length-cells.flat().length} ${text(label('outsidePlot'))}</p></div>`;
  }
