    if(options.highlight){const result=paintJointHighlight(ctx,points,options.highlight,w);canvas.dataset.selectedJoint=options.highlight;canvas.dataset.highlightVisible=String(result.visible);canvas.dataset.highlightedBones=String(result.bones)}
