  async function loadModel(clip,pose){
    if(!clip.pose3d)return null;
    try{if(!modelCache.has(clip.pose3d))modelCache.set(clip.pose3d,(async()=>{const response=await fetch(url(clip.pose3d));if(!response.ok)throw Error('3d');return ReconstructionRegistry.decode(response,clip.pose3d)})());const model=await modelCache.get(clip.pose3d);if(model.frames.length!==pose.frames.length||model.fps!==pose.fps||model.frames.some((f,i)=>f.source_frame!==pose.frames[i].source_frame||f.source_time!==pose.frames[i].source_time))throw Error('alignment');poseModels.set(pose,model);return model}catch(error){return null}
  }
  function nativeAngle(frame,indices){if(frame.available===false)return null;const points=indices.map(i=>frame.anatomy?.[i]);if(points.some(p=>!p||p.length<3||!p.slice(0,3).every(Number.isFinite)))return null;const [a,b,c]=points,u=a.map((v,i)=>v-b[i]),v=c.map((n,i)=>n-b[i]),den=Math.hypot(...u)*Math.hypot(...v);return den<1e-10?null:Math.acos(Math.max(-1,Math.min(1,u.reduce((sum,x,i)=>sum+x*v[i],0)/den)))*180/Math.PI}
  function angleDiagram(key){return `<div class="joint-diagram"><svg class="joint-explainer" viewBox="0 0 210 100" role="img" aria-label="${text(jointName(key))}"><path d="M30 16L94 70L184 70" fill="none" stroke="#658c82" stroke-width="7" stroke-linecap="round"/><path d="M73 49Q90 30 119 70" fill="none" stroke="#a6580c" stroke-width="3"/><circle cx="30" cy="16" r="7"/><circle cx="94" cy="70" r="10" class="middle-joint"/><circle cx="184" cy="70" r="7"/><text x="121" y="44">θ</text></svg><span>${text(jointName(key))}</span></div>`}
  function mountGuide(root,clip,pose,clock,seek){
    let key=state().mechanicMetric||(clip.hand==='L'?'leftElbow':'rightElbow'),smooth=state().smoothCurve!==false;
    const model=poseModels.get(pose);let dimension=model&&state().mechanicsDimension!==2?3:2;
    const imageValues=Object.fromEntries(Object.entries(metricJoints).map(([name,indices])=>[name,pose.frames.map(frame=>PitchPortal.jointAngle(frame,indices))]));
    const nativeJoints={leftKnee:[1,4,7],rightKnee:[2,5,8],leftElbow:[16,18,20],rightElbow:[17,19,21]};
    const modelValues=model?Object.fromEntries(Object.entries(nativeJoints).map(([name,indices])=>[name,model.frames.map(frame=>nativeAngle(frame,indices))])):null;let values=dimension===3?modelValues:imageValues;
    function update(){
      if(!root.isConnected)return;
      const f=Math.max(0,Math.min(pose.frames.length-1,Math.round(clock.currentTime*pose.fps))),svg=root.querySelector('.guided-angle-chart');if(!svg)return;
      const width=Number(svg.dataset.width||720),x=48+f/Math.max(1,pose.frames.length-1)*(width-66),value=values[key][f],valueText=value===null?label('missingValue'):`${value.toFixed(1)}°`;
      svg.querySelector('.guided-cursor').setAttribute('x1',x);svg.querySelector('.guided-cursor').setAttribute('x2',x);svg.setAttribute('aria-valuenow',String(f));svg.setAttribute('aria-valuetext',`${jointName(key)} · ${valueText} · F${f}`);svg.dataset.selectedJoint=key;svg.dataset.currentValue=value===null?'':String(value);
      svg.querySelector('.cursor-value-text').textContent=valueText;
      const bubble=svg.querySelector('.curve-cursor-label'),bubbleWidth=value===null?Math.min(width-66,app.lang==='ko'?106:134):82;
      bubble.querySelector('rect').setAttribute('width',bubbleWidth);bubble.setAttribute('transform',`translate(${Math.max(48,Math.min(width-bubbleWidth-8,x-bubbleWidth/2))},4)`);
      root.querySelector('.guided-angle-value').textContent=valueText;root.querySelector('.guided-frame-value').textContent=`F${String(f).padStart(3,'0')} · ${(f/pose.fps).toFixed(2)} s`;
    }
    function draw(){
      const style=getComputedStyle(root),width=Math.max(240,root.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight)),series=PitchCharts.prepareSeries(values[key],pose.fps,smooth,{bridgeGaps:dimension===2}),paths=PitchCharts.paths(series,width,264,{left:48,right:18,top:40,bottom:38}),arm=key.includes('Elbow'),valid=values[key].filter(v=>v!==null).length;
      root.innerHTML=`<h3 class="curve-source-title">${text(label(dimension===3?'angle3dTitle':'angle2dTitle'))}</h3><div class="mechanics-dimension-switch segmented"><button class="dimension-3" aria-pressed="${dimension===3}" ${model?'':'disabled'}>${text(label('model3d'))}</button><button class="dimension-2" aria-pressed="${dimension===2}">${text(label('projection2d'))}</button></div><p class="mechanics-dimension-note">${text(label(dimension===3?'modelAngleNote':'projectionAngleNote'))}</p><div class="guided-select-row"><label>${text(label('guidedMetric'))}<select class="guided-metric-select">${Object.keys(metricJoints).map(k=>`<option value="${k}" ${k===key?'selected':''}>${text(jointName(k))}</option>`).join('')}</select></label><div class="guided-readout"><span>${text(label('frameValue'))}</span><div class="guided-current-angle"><span class="guided-joint-name">${text(jointName(key))}</span><strong class="guided-angle-value">—</strong></div><small class="guided-frame-value"></small></div></div><div class="metric-purpose"><div>${angleDiagram(key)}</div><div><span class="micro-label">${text(label('watchFor'))}</span><h4>${text(label(arm?'armWatch':'kneeWatch'))}</h4><p>${text(label(arm?'armWhy':'kneeWhy'))}</p></div></div><div class="guided-curve-heading"><h4>${text(label('readableCurve'))}</h4><div class="segmented"><button class="curve-readable" aria-pressed="${smooth}">${text(label('smoothDisplay'))}</button><button class="curve-raw" aria-pressed="${!smooth}">${text(label('rawDisplay'))}</button></div></div><svg class="guided-angle-chart" viewBox="0 0 ${width} 264" data-width="${width}" role="slider" tabindex="0" aria-label="${text(label(key))}" aria-valuemin="0" aria-valuemax="${pose.frames.length-1}" aria-valuenow="0">${[0,45,90,135,180].map(v=>`<line class="guide-grid" x1="48" x2="${width-18}" y1="${paths.y(v)}" y2="${paths.y(v)}"/><text x="32" y="${paths.y(v)+4}" text-anchor="end">${v}°</text>`).join('')}${[0,25,50,75,100].map(v=>`<text x="${48+v/100*(width-66)}" y="248" text-anchor="middle">${v}%</text>`).join('')}${series.gaps.map(([a,b])=>`<rect class="curve-gap-band" x="${paths.x(Math.max(0,a-.5))}" y="40" width="${Math.max(2,paths.x(Math.min(pose.frames.length-1,b+.5))-paths.x(Math.max(0,a-.5)))}" height="186"/>`).join('')}<path class="curve-observed" d="${paths.measured}"/><path class="curve-estimated" d="${paths.estimated}"/><line class="guided-cursor" x1="48" x2="48" y1="34" y2="226"/><g class="curve-cursor-label" transform="translate(48,4)"><rect width="82" height="29" rx="6"/><text class="cursor-value-text" x="9" y="20">—</text></g></svg><div class="curve-reading-legend"><span><i></i>${text(label(dimension===3?'modelLine':'observedLine'))}</span><span><i class="dashed"></i>${text(label('estimatedLine'))}</span><span><i class="gap"></i>${text(label('missingLine'))}</span><small>${valid}/${pose.frames.length} ${text(label(dimension===3?'modelFrames':'validFrames'))}</small></div><p class="axis-caption">${text(label('curveX'))} →</p><details class="metric-explanation" open><summary>${text(label('howRead'))}</summary><p>${text(label('angleRead'))}</p></details><details class="metric-explanation"><summary>${text(label('metricNumbers'))}</summary><p>${text(label(smooth?'smoothNote':'rawNote'))}</p><p>${text(label('angleDefinition'))}</p><p>${text(label('angleLimit'))}</p></details>`;
      root.querySelector('.dimension-3').addEventListener('click',()=>{if(!model)return;dimension=3;values=modelValues;state().mechanicsDimension=3;draw()});root.querySelector('.dimension-2').addEventListener('click',()=>{dimension=2;values=imageValues;state().mechanicsDimension=2;draw()});
      root.querySelector('.guided-metric-select').addEventListener('change',e=>{key=e.target.value;state().mechanicMetric=key;draw()});root.querySelector('.curve-readable').addEventListener('click',()=>{smooth=true;state().smoothCurve=true;draw()});root.querySelector('.curve-raw').addEventListener('click',()=>{smooth=false;state().smoothCurve=false;draw()});
      const chart=root.querySelector('.guided-angle-chart');const pick=event=>{const rect=chart.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,((event.clientX-rect.left)/rect.width*width-48)/(width-66)));seek(Math.round(ratio*(pose.frames.length-1)))};
      let dragging=false;chart.addEventListener('pointerdown',e=>{dragging=true;chart.setPointerCapture(e.pointerId);pick(e)});chart.addEventListener('pointermove',e=>{if(dragging)pick(e)});chart.addEventListener('pointerup',()=>dragging=false);chart.addEventListener('pointercancel',()=>dragging=false);chart.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const f=Math.round(clock.currentTime*pose.fps);seek(e.key==='Home'?0:e.key==='End'?pose.frames.length-1:Math.max(0,Math.min(pose.frames.length-1,f+(e.key==='ArrowRight'?1:-1))))});update();
      root.dataset.selectedJoint=key;root.dataset.angleSource=dimension===3?'model3d':'projection2d';
      root.dispatchEvent(new CustomEvent('jointselectionchange',{bubbles:true,detail:{key,dimension}}));
      if(root.closest('#detail-panel'))window.MotionViewer?.setHighlightedJoint?.(key);
    }
    clock.addEventListener('timeupdate',update);draw();let previousWidth=root.clientWidth;const resize=new ResizeObserver(()=>{if(!root.isConnected){resize.disconnect();return}if(Math.abs(root.clientWidth-previousWidth)>16){previousWidth=root.clientWidth;draw()}});resize.observe(root);
  }
  function mountClip(clip,panel,clock,pose){
    const section=document.createElement('section');section.className='clip-research guided-clip-research';section.innerHTML=`<div class="clip-research-head"><span class="micro-label">${text(label('reportMechanics'))}</span><div><button class="text-btn" id="clip-profile">${text(label('openProfile'))}</button><button class="text-btn" id="clip-compare">${text(label('addCompare'))} +</button><a class="text-link" href="?clip=${encodeURIComponent(clip.id)}#explore">${text(label('shareClip'))}</a></div></div><div class="clip-guided-chart"></div><details class="clip-extra-details"><summary>${text(label('sourceFiles'))}</summary>${[[clip.pose,'raw2d'],[clip.poseRefined,'refined2d'],[clip.pose3d,'raw3d'],[clip.motionQuality,'qualityFile']].filter(([path])=>path).map(([path,key])=>`<a href="${text(url(path))}" target="_blank" rel="noopener noreferrer">${text(label(key))}</a>`).join('')}</details><p class="clip-pitch-link"></p>`;
    panel.querySelector('.detail-body').prepend(section);section.querySelector('#clip-profile').addEventListener('click',()=>PitchPortal.openPlayer(clip.playerCode));section.querySelector('#clip-compare').addEventListener('click',()=>PitchPortal.addComparison(clip.id));section.querySelector('.clip-guided-chart').innerHTML=`<p>${text(label('loading'))}</p>`;loadModel(clip,pose).then(()=>{if(section.isConnected)mountGuide(section.querySelector('.clip-guided-chart'),clip,pose,clock,seekFrame)});
    PitchPortal.fetchPlayer(clip.playerCode).then(d=>{if(!section.isConnected)return;const info=d.clips[clip.id],r=d.records.find(r=>r.id===info?.pitchId);section.querySelector('.clip-pitch-link').innerHTML=r?`${text(label('autoLinkShort'))} · ${text(label('result_'+r.result))} · ${r.balls}–${r.strikes} <a href="${text(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">${text(label('readSource'))} ↗</a>`:text(label('unresolvedLink'))}).catch(()=>{});
  }
  function renderHome(){if(!state().summary)return;const chosen=state().summary.players.filter(p=>p.clipCount>0).sort((a,b)=>b.recordCount-a.recordCount).slice(0,4);$('#home-featured-players').innerHTML=chosen.map(p=>`<button class="home-player" data-home-player="${text(p.code)}"><span class="portrait-wrap">${playerPortrait(stub(p))}</span><span><strong>${text(p.name)}</strong><small>${text(teams(p))} · ${text(label('style_'+p.statistics.archetype))}</small><b>${text(recordCountText(p.recordCount))}</b></span><i>↗</i></button>`).join('');bindPortraits($('#home-featured-players'));document.querySelectorAll('[data-home-player]').forEach(b=>b.addEventListener('click',()=>PitchPortal.openPlayer(b.dataset.homePlayer)))}
  function getAngles(pose,key,model=true){const native={leftKnee:[1,4,7],rightKnee:[2,5,8],leftElbow:[16,18,20],rightElbow:[17,19,21]},three=poseModels.get(pose);return model&&three?three.frames.map(frame=>nativeAngle(frame,native[key])):pose.frames.map(frame=>PitchPortal.jointAngle(frame,metricJoints[key]))}
